package com.ventas.service;
import com.ventas.dto.AuditModels.*;import com.ventas.dto.CatalogModels.Page;import com.ventas.repository.AuditRepository;import com.ventas.security.AuthModels.Identity;import com.ventas.security.AuthFailure;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import java.time.LocalDate;import java.util.*;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Service;
@Service @Profile("db")
public class AuditService {
 private final AuditRepository repo;private final ObjectMapper mapper;public AuditService(AuditRepository repo,ObjectMapper mapper){this.repo=repo;this.mapper=mapper;}
 private void access(Identity actor){if(actor==null||!"ADM".equals(actor.rol())||actor.cambioClaveObligatorio()||!actor.permisos().contains("SEG.BITACORA"))throw new AuthFailure(403,"Solo administración puede consultar la bitácora");}
 public Page<Event> list(Identity a,Filter f){access(a);validate(f);return repo.list(new Filter(f.desde(),f.hasta(),f.usuario().strip(),f.accion().strip(),f.grupo(),f.pagina(),f.tamano()));}
 public Options options(Identity a){access(a);return new Options(repo.actions());}
 public Detail detail(Identity a,long id){access(a);if(id<1)throw new AuthFailure(400,"Evento inválido");var r=repo.detail(id).orElseThrow(()->new AuthFailure(404,"Evento no encontrado"));return new Detail(r.evento(),sanitize(r.anterior()),sanitize(r.nuevo()));}
 void validate(Filter f){if(f.usuario()==null||f.usuario().length()>100||f.accion()==null||!f.accion().matches("[A-Za-z0-9_.-]{0,40}")||!Set.of("","SEGURIDAD","OPERACIONES").contains(Objects.toString(f.grupo(),"INVALID"))||f.pagina()<0||f.pagina()>1000000||f.tamano()<1||f.tamano()>100||f.desde()!=null&&f.hasta()!=null&&f.desde().isAfter(f.hasta())||f.desde()!=null&&(f.desde().getYear()<2000||f.desde().getYear()>9998)||f.hasta()!=null&&(f.hasta().getYear()<2000||f.hasta().getYear()>9998))throw new AuthFailure(400,"Revisa las fechas, filtros y tamaño de página");}
 // Only explicitly recognized business fields leave the audit store. Credentials and unknown fields stay private.
 private static final Set<String> FIELDS=Set.of("estado","estado_anterior","estado_nuevo","estado_venta","estado_orden","estado_cotizacion","usuario","nombres","apellidos","rol","rolId","activo","temporal","nombre","codigo","descripcion","cantidad","cantidad_base","cantidad_anterior","cantidad_nueva","cantidad_contada","precio","precio_normal","precio_oferta","costo","costo_base","total","subtotal","igv","descuento","monto","saldo","deuda","limiteCredito","motivo","fecha","fecha_inicio","fecha_fin","vigente_hasta","revision","venta","comprobante","serie","numero","inicial","ultimo","tipo","producto","presentacion","unidad","id","id_producto","id_presentacion","id_usuario","id_venta","id_caja","id_orden","id_ingreso","id_cotizacion","id_devolucion","cliente","proveedor","formato","valor","anterior","nuevo","lineas","detalle","solicitud","unidades","movimientos_ajuste","lineas_contadas","monto_propuesto","monto_reintegro","forma","medio","receptor","cantidad_etiquetas","simbologia","permisos","sesionesCerradas","modo","validezTributaria");
 JsonNode sanitize(String json){if(json==null)return NullNode.instance;if(json.length()>200000)return TextNode.valueOf("Detalle demasiado extenso para mostrar");try{JsonNode value=mapper.readTree(json);return value!=null&&value.isObject()?clean(value,0,new int[]{0}):NullNode.instance;}catch(Exception e){return TextNode.valueOf("Detalle no disponible");}}
 private JsonNode clean(JsonNode node,int depth,int[] count){if(node==null)return NullNode.instance;if(depth>8||++count[0]>500)return TextNode.valueOf("Detalle limitado");if(node.isObject()){var out=mapper.createObjectNode();node.fields().forEachRemaining(e->{if(FIELDS.contains(e.getKey()))out.set(e.getKey(),clean(e.getValue(),depth+1,count));});return out;}if(node.isArray()){var out=mapper.createArrayNode();for(var item:node){if(out.size()>=100)break;out.add(clean(item,depth+1,count));}return out;}if(node.isTextual()){String value=node.textValue();return TextNode.valueOf(value.length()>500?value.substring(0,500)+"…":value);}return node;}
}
